    "optimizations": {
      "bluetooth": {
        "shortLabel": {
          "type": "string",
          "description": "关闭蓝牙状态块的短标签。",
          "sampleValue": "蓝"
        },
        "stateText": {
          "type": "string",
          "description": "蓝牙关闭后的可用状态文本。",
          "sampleValue": "已关闭"
        }
      },
      "location": {
        "shortLabel": {
          "type": "string",
          "description": "关闭定位状态块的短标签。",
          "sampleValue": "位"
        },
        "stateText": {
          "type": "string",
          "description": "定位关闭后的可用状态文本。",
          "sampleValue": "已关闭"
        }
      },
      "brightness": {
        "shortLabel": {
          "type": "string",
          "description": "降低亮度状态块的短标签。",
          "sampleValue": "亮"
        },
        "stateText": {
          "type": "string",
          "description": "亮度降低后的可用状态文本。",
          "sampleValue": "已关闭"
        }
      },
      "summaryText": {
        "type": "string",
        "description": "三项省电准备都已完成的汇总状态。",
        "sampleValue": "均已关闭"
      }
    }
  },
  "assetCandidates": []
}

